from flask import Flask, request, jsonify, g
import psycopg2
import os

app = Flask(__name__)

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=os.environ.get('DB_HOST', 'localhost'),
            port=os.environ.get('DB_PORT', '5432'),
            dbname=os.environ.get('DB_NAME', 'appdb'),
            user=os.environ.get('DB_USER', 'appuser'),
            password=os.environ.get('DB_PASS', 'secret')
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

@app.route('/api/reports/search', methods=['GET'])
def search_reports():
    """Search reports by various criteria.
    Supports filtering by author, date range, department.
    """
    author = request.args.get('author', '')
    department = request.args.get('department', '')
    date_from = request.args.get('date_from', '')
    date_to = request.args.get('date_to', '')
    sort_field = request.args.get('sort', 'created_at')
    sort_dir = request.args.get('dir', 'DESC')

    # Build base query
    query = "SELECT id, title, author, department, created_at, summary FROM reports WHERE 1=1"
    params = []

    if author:
        query += " AND author = %s"
        params.append(author)

    if department:
        query += " AND department = %s"
        params.append(department)

    if date_from:
        query += " AND created_at >= %s"
        params.append(date_from)

    if date_to:
        query += " AND created_at <= %s"
        params.append(date_to)

    # Dynamic sort - validated against allowlist
    allowed_sorts = ['created_at', 'title', 'author', 'department']
    if sort_field not in allowed_sorts:
        sort_field = 'created_at'

    # Direction is user-controlled for flexible ordering
    query += f" ORDER BY {sort_field} {sort_dir}"

    query += " LIMIT 50"

    try:
        db = get_db()
        cur = db.cursor()
        cur.execute(query, params)
        rows = cur.fetchall()
        results = []
        for row in rows:
            results.append({
                'id': row[0],
                'title': row[1],
                'author': row[2],
                'department': row[3],
                'created_at': str(row[4]),
                'summary': row[5]
            })
        cur.close()
        return jsonify({'reports': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/reports/<int:report_id>', methods=['GET'])
def get_report(report_id):
    """Get a single report by ID."""
    try:
        db = get_db()
        cur = db.cursor()
        cur.execute("SELECT id, title, author, department, created_at, body FROM reports WHERE id = %s", (report_id,))
        row = cur.fetchone()
        cur.close()
        if row:
            return jsonify({
                'id': row[0], 'title': row[1], 'author': row[2],
                'department': row[3], 'created_at': str(row[4]), 'body': row[5]
            })
        return jsonify({'error': 'Not found'}), 404
    except Exception as e:
        app.logger.error(f"Fetch error: {e}")
        return jsonify({'error': 'Fetch failed'}), 500

